const body = $input.first().json.body;
const transcript = body.transcript || '';

// Build messages array from conversation history + current transcript
const history = (body.conversation_history || []).map(h => ({
  role: h.role,
  content: String(h.content)
}));
const messages = [...history, { role: 'user', content: transcript }];

// Question detection heuristic
const questionWords = ['what', 'how', 'why', 'when', 'where', 'who', 'tell me', 'describe', 'explain', 'can you', 'could you', 'would you', 'have you', 'do you', 'are you', 'walk me through', 'share', 'give me an example'];
const lowerTranscript = transcript.toLowerCase();
const is_question = questionWords.some(w => lowerTranscript.includes(w)) || transcript.trim().endsWith('?');

return [{
  json: {
    session_id: body.session_id || 'default',
    job_role: body.job_role || 'Software Engineer',
    company: body.company || 'the company',
    messages: messages,
    transcript: transcript,
    is_question: is_question
  }
}];

// Handle both array-as-single-item and multiple-items responses from Supabase
const firstItem = $input.first().json;
let chunks;
if (Array.isArray(firstItem)) {
  // n8n wrapped the JSON array as a single item
  chunks = firstItem;
} else {
  // n8n split the array into multiple items (or single result)
  chunks = $input.all().map(i => i.json).filter(c => c && c.content);
}

const context = $('Code: Build Context').first().json;

const ragContext = chunks.length > 0 && chunks[0] && chunks[0].content
  ? chunks.slice(0, 3).map((c, i) => `[Resume Section ${i + 1}]\n${c.content}`).join('\n\n')
  : 'No resume context available — answer based on general best practices.';

return [{
  json: {
    ...context,
    rag_context: ragContext,
    rag_count: chunks.length
  }
}];

// chainLlm outputs $json.text (not $json.content[0].text like the HTTP Anthropic node)
const responseText = $json.text || '';
const context = $('Code: Inject RAG Context').first().json;

// Strip markdown formatting — TTS speaks raw text
let cleaned = responseText
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/#{1,6}\s/g, '')
  .replace(/[-*+]\s{1,}/g, '')
  .replace(/\n{2,}/g, ' ')
  .replace(/\n/g, ' ')
  .trim();

// Truncate to ~500 chars (~35 seconds of speech at normal pace)
if (cleaned.length > 500) {
  const lastPeriod = cleaned.lastIndexOf('.', 500);
  cleaned = lastPeriod > 300 ? cleaned.substring(0, lastPeriod + 1) : cleaned.substring(0, 500);
}

return [{
  json: {
    answer_text: cleaned,
    session_id: context.session_id,
    transcript: context.transcript
  }
}];

const item = $input.first();
const binaryData = item.binary?.data;
const cleanData = $('Code: Clean for TTS').first().json;

let audioBase64 = '';
let mimeType = 'audio/mpeg';

if (binaryData) {
  mimeType = binaryData.mimeType || 'audio/mpeg';
  const rawData = String(binaryData.data || '');

  if (rawData && !rawData.startsWith('filesystem')) {
    // In-memory mode: .data is already a base64 string
    audioBase64 = rawData;
  } else {
    // Filesystem mode (binaryMode=separate): use getBinaryDataBuffer with timeout
    try {
      const buf = await Promise.race([
        this.helpers.getBinaryDataBuffer(0, 'data'),
        new Promise((_, rej) => setTimeout(() => rej(new Error('binary read timeout')), 8000))
      ]);
      audioBase64 = buf.toString('base64');
    } catch(e) {
      audioBase64 = ''; // Audio processed but can't encode in this mode
    }
  }
}

return [{
  json: {
    success: true,
    answer_text: cleanData.answer_text,
    audio_base64: audioBase64,
    audio_content_type: mimeType,
    session_id: cleanData.session_id,
    transcript: cleanData.transcript,
    timestamp: new Date().toISOString()
  }
}];

const errorData = $input.first().json;
const fallbacks = [
  "I'm processing that, give me just a moment.",
  "Let me think about that briefly.",
  "That's a great question, let me gather my thoughts.",
  "I want to give you a thorough answer, one second."
];

const randomFallback = fallbacks[Math.floor(Math.random() * fallbacks.length)];

return [{
  json: {
    success: false,
    answer_text: randomFallback,
    audio_base64: '',
    error: errorData.error?.message || errorData.message || 'Processing error',
    timestamp: new Date().toISOString()
  }
}];

